select eto_ofr_display_id, fk_glusr_usr_id, eto_ofr_mcat_id, eto_ofr_typ, eto_ofr_approv, eto_ofr_approv_date_orig
from im_dwh_rpt.fact_eto_ofr_expired 
where eto_ofr_typ = 'B' and eto_ofr_approv = 'A'
limit 50000;





-- =====================================================================
-- Q1a: Get all LLM extractions for a single GLID + MCAT pair
-- Params: {{glid}} (integer), {{mcat_id}} (integer)
SELECT
    fel.id,
    fel.file_id,
    fel.extracted_at,
    fel.llm_extracted_json_masked
FROM pns_insight.file_extraction_logs fel
JOIN pns_insight.files f        ON f.id = fel.file_id
JOIN pns_insight.participants p ON p.file_id = f.id
WHERE p.user_glid   = {{ glid }}
  AND f.src_mcat_id = {{ mcat_id }}
  AND f.is_active   = true
  AND p.is_active   = true
  AND fel.is_active = true;

-- Q1b: Batch version — one-to-one (glid, mcat_id) pairs
-- Edit the IN list: each tuple is (glid, mcat_id)
SELECT
    fel.id,
    fel.file_id,
    p.user_glid,
    f.src_mcat_id,
    fel.extracted_at,
    fel.llm_extracted_json_masked
FROM pns_insight.file_extraction_logs fel
JOIN pns_insight.files f        ON f.id = fel.file_id
JOIN pns_insight.participants p ON p.file_id = f.id
WHERE (p.user_glid, f.src_mcat_id) IN (
    (111111, 101),
    (222222, 202),
    (333333, 303)
)
  AND f.is_active   = true
  AND p.is_active   = true
  AND fel.is_active = true;

-- =====================================================================
-- Q2: Schema of all pns_insight tables (ClickHouse)

SELECT
    table,
    name,
    type,
    default_expression,
    comment
FROM system.columns
WHERE database = 'pns_insight'
ORDER BY table, position;

